def sl(v):return "'"+v.replace("'","''")+"'"
def sql_data(d):return sl(json.dumps(d,ensure_ascii=False,separators=(',',':')))+'::jsonb'
def insert(module, title, slug, data, published=True):
 status='published' if published else 'draft'
 stamp='now()' if published else 'null'
 return f"INSERT INTO public.records (module,title,slug,status,data,published_at) VALUES ({sl(module)},{sl(title)},{sl(slug)},{sl(status)},{sql_data(data)},{stamp}) ON CONFLICT (module,slug) DO UPDATE SET title=EXCLUDED.title,status=EXCLUDED.status,data=COALESCE(public.records.data,'{{}}'::jsonb)||EXCLUDED.data,updated_at=now(),published_at={stamp};"

# Complete v2 baseline + non-destructive content expansion in same transaction.
v2=(ROOT/'xarmoured_initial_seed_v2_company_only.sql').read_text()
pos=v2.index('\ncommit;')
